);

CREATE TABLE "service_requests" (
	"id" text PRIMARY KEY NOT NULL,
	"draft_id" text NOT NULL,
	"owner_id" text NOT NULL,
	"organization" text NOT NULL,
	"service_type" text NOT NULL,
	"title" text NOT NULL,
	"details" text NOT NULL,
	"status" text DEFAULT 'submitted' NOT NULL,
	"idempotency_key" text NOT NULL,
	"created_at" integer NOT NULL,
	FOREIGN KEY ("draft_id") REFERENCES "service_drafts"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("owner_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action
);

CREATE UNIQUE INDEX "service_requests_draft_id_unique" ON "service_requests" ("draft_id");

CREATE UNIQUE INDEX "service_requests_owner_idempotency_idx" ON "service_requests" ("owner_id","idempotency_key");

CREATE TABLE "rate_limits" (
	"bucket_key" text PRIMARY KEY NOT NULL,
	"window_start" integer NOT NULL,
	"count" integer DEFAULT 1 NOT NULL,
	"expires_at" integer NOT NULL
);

ALTER TABLE "sessions" ADD "csrf_hash" text NOT NULL DEFAULT '';

CREATE TABLE "departments" (
  "id" text PRIMARY KEY NOT NULL,
  "organization" text NOT NULL,
  "code" text NOT NULL,
  "name" text NOT NULL,
  "accepts_requests" integer DEFAULT 1 NOT NULL
);

CREATE UNIQUE INDEX "departments_org_code_unique" ON "departments" ("organization","code");

CREATE TABLE "organization_memberships" (
  "id" text PRIMARY KEY NOT NULL,
  "user_id" text NOT NULL,
  "organization" text NOT NULL,
  "department_id" text,
  "role" text DEFAULT 'customer_member' NOT NULL,
  "status" text DEFAULT 'active' NOT NULL,
  "created_at" integer NOT NULL,
  FOREIGN KEY ("user_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE cascade,
  FOREIGN KEY ("department_id") REFERENCES "departments"("id") ON UPDATE no action ON DELETE no action
);

CREATE UNIQUE INDEX "memberships_user_org_unique" ON "organization_memberships" ("user_id","organization");

